css:
.mn4-dropdown-stagger{
  --mn4-ds-line:rgba(255,255,255,.10);
  --mn4-ds-txt:#E8EBF4;
  --mn4-ds-dim:#8C93A8;
  --mn4-ds-accent:#8AA6FF;
  box-sizing:border-box;position:relative;width:232px;min-height:150px;
  font:500 12px/1.2 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--mn4-ds-txt);-webkit-font-smoothing:antialiased;
}
.mn4-dropdown-stagger *{box-sizing:border-box}
.mn4-dropdown-stagger svg{width:14px;height:14px;display:block;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.mn4-dropdown-stagger-trigger{
  display:flex;align-items:center;gap:8px;width:100%;height:32px;padding:0 8px;
  border:1px solid var(--mn4-ds-line);border-radius:10px;color:inherit;font:inherit;cursor:pointer;
  background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.02));
  transition:transform .18s cubic-bezier(.2,.8,.3,1),border-color .18s ease,background .18s ease;
}
.mn4-dropdown-stagger-trigger:hover{border-color:rgba(255,255,255,.22)}
.mn4-dropdown-stagger-trigger:active{transform:scale(.975)}
.mn4-dropdown-stagger-trigger:focus-visible{outline:2px solid var(--mn4-ds-accent);outline-offset:2px}
.mn4-dropdown-stagger-badge{display:grid;place-items:center;width:20px;height:20px;border-radius:6px;font-size:9px;font-weight:700;letter-spacing:.04em;color:#0A0C12;background:linear-gradient(135deg,#7E9BFF,#B472FF)}
.mn4-dropdown-stagger-title{flex:1;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mn4-dropdown-stagger-chev{color:var(--mn4-ds-dim);transition:transform .3s cubic-bezier(.2,.9,.25,1.2),color .2s ease}
.mn4-dropdown-stagger[data-open="true"] .mn4-dropdown-stagger-chev{transform:rotate(180deg);color:var(--mn4-ds-txt)}
.mn4-dropdown-stagger-panel{
  position:absolute;left:0;right:0;top:36px;padding:4px;z-index:5;
  border:1px solid var(--mn4-ds-line);border-radius:12px;
  background:linear-gradient(180deg,#171C29,#10141E);
  box-shadow:0 18px 34px -18px rgba(0,0,0,.95),0 0 0 1px rgba(0,0,0,.35);
  transform-origin:top center;opacity:0;visibility:hidden;transform:translateY(-6px) scale(.97);
  transition:opacity .16s ease,transform .28s cubic-bezier(.2,.9,.25,1.2),visibility 0s linear .2s;
}
.mn4-dropdown-stagger[data-open="true"] .mn4-dropdown-stagger-panel{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.mn4-dropdown-stagger-item{
  display:flex;align-items:center;gap:8px;width:100%;height:24px;padding:0 7px;border:0;border-radius:8px;
  background:transparent;color:var(--mn4-ds-txt);font:inherit;text-align:left;cursor:pointer;
  opacity:0;transform:translateY(-7px);
  transition:opacity .2s ease,transform .34s cubic-bezier(.2,.9,.25,1.25),background .15s ease,box-shadow .15s ease;
}
.mn4-dropdown-stagger-item>span{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mn4-dropdown-stagger-ico{color:var(--mn4-ds-dim);transition:color .16s ease,transform .3s cubic-bezier(.2,.9,.25,1.3)}
.mn4-dropdown-stagger[data-open="true"] .mn4-dropdown-stagger-item{opacity:1;transform:none}
.mn4-dropdown-stagger[data-open="true"] .mn4-dropdown-stagger-item:nth-child(1){transition-delay:.02s}
.mn4-dropdown-stagger[data-open="true"] .mn4-dropdown-stagger-item:nth-child(2){transition-delay:.06s}
.mn4-dropdown-stagger[data-open="true"] .mn4-dropdown-stagger-item:nth-child(3){transition-delay:.1s}
.mn4-dropdown-stagger[data-open="true"] .mn4-dropdown-stagger-item:nth-child(5){transition-delay:.14s}
.mn4-dropdown-stagger-item:hover:not(:disabled){background:rgba(255,255,255,.07)}
.mn4-dropdown-stagger-item:focus-visible{outline:none;background:rgba(255,255,255,.07);box-shadow:inset 0 0 0 1px var(--mn4-ds-accent)}
.mn4-dropdown-stagger-item:hover:not(:disabled) .mn4-dropdown-stagger-ico,
.mn4-dropdown-stagger-item:focus-visible .mn4-dropdown-stagger-ico{color:var(--mn4-ds-accent);transform:translateX(1px) scale(1.1)}
.mn4-dropdown-stagger-item:active:not(:disabled){transform:scale(.985)}
.mn4-dropdown-stagger-item:disabled{opacity:.34;cursor:not-allowed}
.mn4-dropdown-stagger-kbd{font:600 9px/1 inherit;color:var(--mn4-ds-dim);border:1px solid var(--mn4-ds-line);border-radius:4px;padding:3px 4px}
.mn4-dropdown-stagger-sep{height:1px;margin:3px 6px;background:var(--mn4-ds-line)}
.mn4-dropdown-stagger-item.mn4-dropdown-stagger-fired{animation:mn4-dropdown-stagger-flash .42s ease}
@keyframes mn4-dropdown-stagger-flash{0%{background:rgba(138,166,255,.4)}100%{background:transparent}}
@media (prefers-reduced-motion:reduce){
  .mn4-dropdown-stagger-panel,.mn4-dropdown-stagger-item,.mn4-dropdown-stagger-chev,.mn4-dropdown-stagger-trigger,.mn4-dropdown-stagger-ico{transition-duration:.01ms !important;transition-delay:0s !important;animation:none !important}
}

js:
var trigger = root.querySelector('.mn4-dropdown-stagger-trigger');
var all = Array.prototype.slice.call(root.querySelectorAll('.mn4-dropdown-stagger-item'));
var isOpen = false;
function live(){ return all.filter(function(b){ return !b.disabled; }); }
function focusAt(i){ var l = live(); var el = l[(i + l.length) % l.length]; if (el) el.focus({preventScroll:true}); }
function setOpen(v, idx){
  isOpen = v;
  root.setAttribute('data-open', v ? 'true' : 'false');
  trigger.setAttribute('aria-expanded', v ? 'true' : 'false');
  if (v && typeof idx === 'number') focusAt(idx);
}
trigger.addEventListener('click', function(){
  if (isOpen) { setOpen(false); trigger.focus({preventScroll:true}); } else { setOpen(true, 0); }
});
trigger.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); setOpen(true, e.key === 'ArrowUp' ? -1 : 0); }
});
root.addEventListener('keydown', function(e){
  if (e.key === 'Escape' && isOpen) { e.stopPropagation(); setOpen(false); trigger.focus({preventScroll:true}); return; }
  if (!isOpen) return;
  var l = live(); var i = l.indexOf(document.activeElement);
  if (e.key === 'ArrowDown') { e.preventDefault(); focusAt(i + 1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); focusAt(i < 0 ? -1 : i - 1); }
  else if (e.key === 'Home') { e.preventDefault(); focusAt(0); }
  else if (e.key === 'End') { e.preventDefault(); focusAt(-1); }
  else if (e.key === 'Tab') { setOpen(false); }
});
all.forEach(function(btn){
  btn.addEventListener('click', function(){
    if (btn.disabled) return;
    btn.classList.add('mn4-dropdown-stagger-fired');
    setTimeout(function(){ btn.classList.remove('mn4-dropdown-stagger-fired'); }, 440);
    setOpen(false);
    trigger.focus({preventScroll:true});
  });
});
root.addEventListener('focusout', function(){
  setTimeout(function(){ if (isOpen && !root.contains(document.activeElement)) setOpen(false); }, 0);
});

css:
.mn4-context-submenu{
  --mn4-cx-line:rgba(255,255,255,.11);
  --mn4-cx-txt:#E9ECF5;
  --mn4-cx-dim:#8B93A8;
  --mn4-cx-accent:#7CE0C0;
  --mn4-cx-danger:#FF7B7B;
  box-sizing:border-box;position:relative;width:288px;height:150px;
  font:500 11.5px/1.2 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--mn4-cx-txt);-webkit-font-smoothing:antialiased;
}
.mn4-context-submenu *{box-sizing:border-box}
.mn4-context-submenu svg{width:13px;height:13px;display:block;flex:none;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.mn4-context-submenu-surface{
  position:absolute;inset:0;border:1px dashed rgba(255,255,255,.14);border-radius:12px;overflow:hidden;
  background:radial-gradient(120% 100% at 50% 0,rgba(124,224,192,.08),rgba(255,255,255,0) 60%),#0E1220;
  display:grid;place-items:center;cursor:context-menu;
  transition:border-color .2s ease,box-shadow .2s ease;
