.mn4-context-submenu-surface:hover{border-color:rgba(255,255,255,.24)}
.mn4-context-submenu-surface:focus-visible{outline:2px solid var(--mn4-cx-accent);outline-offset:2px}
.mn4-context-submenu-grid{position:absolute;inset:0;opacity:.5;
  background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);
  background-size:18px 18px}
.mn4-context-submenu-hint{display:flex;align-items:center;gap:6px;color:var(--mn4-cx-dim);font-size:11px;letter-spacing:.01em;transition:opacity .2s ease}
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-hint{opacity:.25}
.mn4-context-submenu-menu{
  position:absolute;top:0;left:0;width:158px;padding:4px;z-index:6;
  border:1px solid var(--mn4-cx-line);border-radius:11px;
  background:linear-gradient(180deg,#181D2B,#11151F);
  box-shadow:0 20px 36px -20px rgba(0,0,0,.95),0 0 0 1px rgba(0,0,0,.4);
  opacity:0;visibility:hidden;transform:scale(.9);transform-origin:top left;
  transition:opacity .13s ease,transform .24s cubic-bezier(.2,.9,.25,1.3),visibility 0s linear .16s;
}
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-menu{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.mn4-context-submenu-item{
  display:flex;align-items:center;gap:7px;width:100%;height:24px;padding:0 6px;border:0;border-radius:7px;
  background:transparent;color:inherit;font:inherit;text-align:left;cursor:pointer;
  opacity:0;transform:translateX(-5px);
  transition:opacity .18s ease,transform .3s cubic-bezier(.2,.9,.25,1.25),background .14s ease,color .14s ease;
}
.mn4-context-submenu-item>span{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mn4-context-submenu-item kbd{font:600 9px/1 inherit;color:var(--mn4-cx-dim)}
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-item{opacity:1;transform:none}
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-menu>*:nth-child(1) .mn4-context-submenu-item,
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-menu>.mn4-context-submenu-item:nth-child(1){transition-delay:.02s}
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-menu>.mn4-context-submenu-item:nth-child(2){transition-delay:.05s}
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-menu>.mn4-context-submenu-branch .mn4-context-submenu-item{transition-delay:.08s}
.mn4-context-submenu[data-open="true"] .mn4-context-submenu-menu>.mn4-context-submenu-item:nth-child(5){transition-delay:.11s}
.mn4-context-submenu-item:hover,.mn4-context-submenu-item:focus-visible,
.mn4-context-submenu-item[aria-expanded="true"]{background:rgba(255,255,255,.08);outline:none}
.mn4-context-submenu-item:focus-visible{box-shadow:inset 0 0 0 1px var(--mn4-cx-accent)}
.mn4-context-submenu-danger{color:var(--mn4-cx-danger)}
.mn4-context-submenu-danger:hover,.mn4-context-submenu-danger:focus-visible{background:rgba(255,123,123,.14)}
.mn4-context-submenu-sep{height:1px;margin:3px 5px;background:var(--mn4-cx-line)}
.mn4-context-submenu-branch{position:relative}
.mn4-context-submenu-caret{width:11px;height:11px;color:var(--mn4-cx-dim);transition:transform .22s ease}
.mn4-context-submenu-branch[data-sub="true"] .mn4-context-submenu-caret{transform:translateX(2px)}
.mn4-context-submenu-sub{
  position:absolute;top:-5px;left:calc(100% + 3px);width:118px;padding:4px;
  border:1px solid var(--mn4-cx-line);border-radius:10px;
  background:linear-gradient(180deg,#1B2130,#131824);
  box-shadow:0 16px 30px -18px rgba(0,0,0,.95);
  opacity:0;visibility:hidden;transform:translateX(-6px) scale(.96);transform-origin:top left;
  transition:opacity .14s ease,transform .26s cubic-bezier(.2,.9,.25,1.3),visibility 0s linear .16s;
}
.mn4-context-submenu-branch[data-flip="true"] .mn4-context-submenu-sub{left:auto;right:calc(100% + 3px);transform-origin:top right;transform:translateX(6px) scale(.96)}
.mn4-context-submenu-branch[data-sub="true"] .mn4-context-submenu-sub{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.mn4-context-submenu-subitem{
  display:block;width:100%;height:23px;padding:0 7px;border:0;border-radius:6px;background:transparent;
  color:inherit;font:inherit;text-align:left;cursor:pointer;opacity:0;transform:translateY(-4px);
  transition:opacity .16s ease,transform .26s cubic-bezier(.2,.9,.25,1.25),background .14s ease;
}
.mn4-context-submenu-branch[data-sub="true"] .mn4-context-submenu-subitem{opacity:1;transform:none}
.mn4-context-submenu-branch[data-sub="true"] .mn4-context-submenu-subitem:nth-child(2){transition-delay:.04s}
.mn4-context-submenu-branch[data-sub="true"] .mn4-context-submenu-subitem:nth-child(3){transition-delay:.08s}
.mn4-context-submenu-subitem:hover,.mn4-context-submenu-subitem:focus-visible{background:rgba(124,224,192,.16);outline:none}
.mn4-context-submenu-out{
  position:absolute;left:8px;bottom:7px;font-size:10px;letter-spacing:.02em;color:var(--mn4-cx-dim);
  padding:2px 7px;border-radius:999px;border:1px solid var(--mn4-cx-line);background:rgba(10,12,18,.7);
}
@media (prefers-reduced-motion:reduce){
  .mn4-context-submenu-menu,.mn4-context-submenu-item,.mn4-context-submenu-sub,.mn4-context-submenu-subitem,.mn4-context-submenu-caret{transition-duration:.01ms !important;transition-delay:0s !important}
}

js:
var surface = root.querySelector('.mn4-context-submenu-surface');
var menu = root.querySelector('.mn4-context-submenu-menu');
var branch = root.querySelector('.mn4-context-submenu-branch');
var subTrigger = root.querySelector('.mn4-context-submenu-subtrigger');
var sub = root.querySelector('.mn4-context-submenu-sub');
var out = root.querySelector('.mn4-context-submenu-out');
var tops = Array.prototype.slice.call(root.querySelectorAll('[data-top]'));
var subs = Array.prototype.slice.call(root.querySelectorAll('.mn4-context-submenu-subitem'));
var hoverTimer = null;
var open = false;
function closeSub(){ if (hoverTimer) clearTimeout(hoverTimer); branch.setAttribute('data-sub','false'); subTrigger.setAttribute('aria-expanded','false'); }
function openSub(focusFirst){
  if (hoverTimer) clearTimeout(hoverTimer);
  var gap = 7;
  var rootW = root.clientWidth, rootH = root.clientHeight;
  var subW = sub.offsetWidth, subH = sub.offsetHeight;
  var space = rootW - (menu.offsetLeft + menu.offsetWidth);
  if (space < subW + gap) {
    var shifted = Math.max(4, rootW - subW - menu.offsetWidth - gap);
    if (rootW - (shifted + menu.offsetWidth) > space) {
      menu.style.left = shifted + 'px';
      space = rootW - (shifted + menu.offsetWidth);
    }
  }
  branch.setAttribute('data-flip', space < subW ? 'true' : 'false');
  var anchor = menu.offsetTop + branch.offsetTop;
  var overshoot = anchor - 5 + subH - (rootH - 4);
  sub.style.top = (overshoot > 0 ? -5 - overshoot : -5) + 'px';
  branch.setAttribute('data-sub','true');
  subTrigger.setAttribute('aria-expanded','true');
  if (focusFirst) subs[0].focus({preventScroll:true});
}
function close(){ open = false; root.setAttribute('data-open','false'); closeSub(); }
function openAt(x, y){
  root.setAttribute('data-open','true');
  open = true;
  closeSub();
  var mw = menu.offsetWidth, mh = menu.offsetHeight;
  menu.style.left = Math.max(4, Math.min(x, root.clientWidth - mw - 4)) + 'px';
  menu.style.top = Math.max(4, Math.min(y, root.clientHeight - mh - 4)) + 'px';
  tops[0].focus({preventScroll:true});
}
surface.addEventListener('contextmenu', function(e){
  e.preventDefault();
  var r = root.getBoundingClientRect();
  openAt(e.clientX - r.left, e.clientY - r.top);
  out.textContent = 'Menu at ' + Math.round(e.clientX - r.left) + ', ' + Math.round(e.clientY - r.top);
});
surface.addEventListener('pointerdown', function(){ if (open) close(); });
surface.addEventListener('keydown', function(e){
  if (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10') || e.key === 'Enter') { e.preventDefault(); openAt(46, 34); out.textContent = 'Menu opened by keyboard'; }
});
branch.addEventListener('pointerenter', function(){ if (hoverTimer) clearTimeout(hoverTimer); hoverTimer = setTimeout(function(){ openSub(false); }, 90); });
branch.addEventListener('pointerleave', function(){ if (hoverTimer) clearTimeout(hoverTimer); hoverTimer = setTimeout(closeSub, 160); });
subTrigger.addEventListener('click', function(e){ e.preventDefault(); if (branch.getAttribute('data-sub') === 'true') closeSub(); else openSub(true); });
root.addEventListener('keydown', function(e){
  if (!open) return;
  if (e.key === 'Escape') {
    e.stopPropagation();
    if (branch.getAttribute('data-sub') === 'true') { closeSub(); subTrigger.focus({preventScroll:true}); }
    else { close(); surface.focus({preventScroll:true}); }
    return;
  }
  var inSub = subs.indexOf(document.activeElement) > -1;
  var list = inSub ? subs : tops;
  var i = list.indexOf(document.activeElement);
  if (e.key === 'ArrowDown') { e.preventDefault(); list[(i + 1) % list.length].focus({preventScroll:true}); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); list[(i - 1 + list.length) % list.length].focus({preventScroll:true}); }
  else if (e.key === 'ArrowRight' && document.activeElement === subTrigger) { e.preventDefault(); openSub(true); }
  else if (e.key === 'ArrowLeft' && inSub) { e.preventDefault(); closeSub(); subTrigger.focus({preventScroll:true}); }
  else if (e.key === 'Tab') { e.preventDefault(); }
});
tops.concat(subs).forEach(function(btn){
  if (btn === subTrigger) return;
  btn.addEventListener('click', function(){
    out.textContent = (btn.querySelector('span') || btn).textContent.trim();
    close();
    surface.focus({preventScroll:true});
  });
});
root.addEventListener('focusout', function(){
  setTimeout(function(){ if (open && !root.contains(document.activeElement)) close(); }, 0);
});

css:
.mn4-radial-arc{
  --mn4-ra-r:58px;
  --mn4-ra-a:0deg;
  --mn4-ra-line:rgba(255,255,255,.12);
  --mn4-ra-txt:#EAEDF6;
  --mn4-ra-dim:#8B93A8;
  --mn4-ra-accent:#FFB35C;
  box-sizing:border-box;position:relative;width:260px;height:150px;display:flex;flex-direction:column;align-items:center;
  font:600 11px/1.2 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--mn4-ra-txt);-webkit-font-smoothing:antialiased;
}
.mn4-radial-arc *{box-sizing:border-box}
.mn4-radial-arc svg{width:15px;height:15px;display:block;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.mn4-radial-arc-stage{position:relative;width:100%;height:122px}
.mn4-radial-arc-sweep{
  position:absolute;left:50%;bottom:0;width:150px;height:80px;margin-left:-75px;border-radius:150px 150px 0 0;
  background:radial-gradient(80% 100% at 50% 100%,rgba(255,179,92,.18),rgba(255,179,92,0) 70%);
  opacity:0;transform:scale(.5);transform-origin:50% 100%;
  transition:opacity .3s ease,transform .5s cubic-bezier(.2,.9,.25,1.1);
}
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-sweep{opacity:1;transform:none}
.mn4-radial-arc-items{position:absolute;left:50%;bottom:25px;width:0;height:0}
.mn4-radial-arc-item{
  position:absolute;left:-16px;top:-16px;width:32px;height:32px;display:grid;place-items:center;
  border:1px solid var(--mn4-ra-line);border-radius:50%;color:var(--mn4-ra-txt);cursor:pointer;
  background:linear-gradient(180deg,#1D2331,#151A26);
  box-shadow:0 8px 18px -10px rgba(0,0,0,.9);
  opacity:0;transform:scale(.3);
  transition:opacity .18s ease,transform .42s cubic-bezier(.3,1.35,.5,1),border-color .18s ease,color .18s ease;
}
.mn4-radial-arc-item:nth-child(1){--mn4-ra-a:-76deg}
.mn4-radial-arc-item:nth-child(2){--mn4-ra-a:-38deg}
.mn4-radial-arc-item:nth-child(3){--mn4-ra-a:0deg}
.mn4-radial-arc-item:nth-child(4){--mn4-ra-a:38deg}
.mn4-radial-arc-item:nth-child(5){--mn4-ra-a:76deg}
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item{
  opacity:1;
  transform:rotate(var(--mn4-ra-a)) translateY(calc(-1 * var(--mn4-ra-r))) rotate(calc(-1 * var(--mn4-ra-a)));
}
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:nth-child(3){transition-delay:.02s}
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:nth-child(2),
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:nth-child(4){transition-delay:.06s}
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:nth-child(1),
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:nth-child(5){transition-delay:.1s}
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:hover,
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:focus-visible{
  border-color:var(--mn4-ra-accent);color:var(--mn4-ra-accent);outline:none;
  transform:rotate(var(--mn4-ra-a)) translateY(calc(-1 * var(--mn4-ra-r) - 5px)) rotate(calc(-1 * var(--mn4-ra-a))) scale(1.12);
}
.mn4-radial-arc[data-open="true"] .mn4-radial-arc-item:focus-visible{box-shadow:0 0 0 2px rgba(255,179,92,.45)}
