js:
var hub = root.querySelector('.mn4-radial-arc-hub');
var caption = root.querySelector('.mn4-radial-arc-caption');
var items = Array.prototype.slice.call(root.querySelectorAll('.mn4-radial-arc-item'));
var open = false;
var idle = 'Quick add';
function say(t){ caption.textContent = t; }
function setOpen(v, focusIdx){
  open = v;
  root.setAttribute('data-open', v ? 'true' : 'false');
  hub.setAttribute('aria-expanded', v ? 'true' : 'false');
  if (v) { say('Choose an action'); if (typeof focusIdx === 'number') items[focusIdx].focus({preventScroll:true}); }
  else { say(idle); }
}
hub.addEventListener('click', function(){
  if (open) { setOpen(false); hub.focus({preventScroll:true}); } else { setOpen(true, 2); }
});
items.forEach(function(btn){
  btn.addEventListener('pointerenter', function(){ if (open) say(btn.getAttribute('data-label')); });
  btn.addEventListener('focus', function(){ if (open) say(btn.getAttribute('data-label')); });
  btn.addEventListener('click', function(){
    idle = 'Added ' + btn.getAttribute('data-label').toLowerCase();
    setOpen(false);
    hub.focus({preventScroll:true});
  });
});
root.addEventListener('keydown', function(e){
  if (e.key === 'Escape' && open) { e.stopPropagation(); setOpen(false); hub.focus({preventScroll:true}); return; }
  if (!open) return;
  var i = items.indexOf(document.activeElement);
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); items[(i + 1 + items.length) % items.length].focus({preventScroll:true}); }
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); items[(i - 1 + items.length) % items.length].focus({preventScroll:true}); }
  else if (e.key === 'Home') { e.preventDefault(); items[0].focus({preventScroll:true}); }
  else if (e.key === 'End') { e.preventDefault(); items[items.length - 1].focus({preventScroll:true}); }
});
root.addEventListener('pointerleave', function(){ if (open) say('Choose an action'); });
root.addEventListener('focusout', function(){
  setTimeout(function(){ if (open && !root.contains(document.activeElement)) setOpen(false); }, 0);
});

