js:
var tab = root.querySelector('.mn4-mega-columns-tab');
var panel = root.querySelector('.mn4-mega-columns-panel');
var links = Array.prototype.slice.call(root.querySelectorAll('.mn4-mega-columns-link'));
var cols = Array.prototype.slice.call(root.querySelectorAll('.mn4-mega-columns-col'));
var timer = null;
var open = false;
function setOpen(v){
  if (timer) { clearTimeout(timer); timer = null; }
  open = v;
  root.setAttribute('data-open', v ? 'true' : 'false');
  tab.setAttribute('aria-expanded', v ? 'true' : 'false');
}
function delayed(v, ms){ if (timer) clearTimeout(timer); timer = setTimeout(function(){ setOpen(v); }, ms); }
tab.addEventListener('pointerenter', function(){ delayed(true, 70); });
tab.addEventListener('click', function(){ if (open) { setOpen(false); } else { setOpen(true); } });
tab.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown') { e.preventDefault(); setOpen(true); links[0].focus({preventScroll:true}); }
});
root.addEventListener('pointerleave', function(){ delayed(false, 180); });
panel.addEventListener('pointerenter', function(){ if (timer) { clearTimeout(timer); timer = null; } });
root.addEventListener('keydown', function(e){
  if (e.key === 'Escape' && open) { e.stopPropagation(); setOpen(false); tab.focus({preventScroll:true}); return; }
  if (!open) return;
  var i = links.indexOf(document.activeElement);
  if (i < 0) return;
  var col = Math.floor(i / 3), row = i % 3, next = -1;
  if (e.key === 'ArrowDown') next = col * 3 + Math.min(2, row + 1);
  else if (e.key === 'ArrowUp') next = row === 0 ? -2 : col * 3 + row - 1;
  else if (e.key === 'ArrowRight') next = ((col + 1) % cols.length) * 3 + row;
  else if (e.key === 'ArrowLeft') next = ((col - 1 + cols.length) % cols.length) * 3 + row;
  if (next === -2) { e.preventDefault(); tab.focus({preventScroll:true}); }
  else if (next > -1) { e.preventDefault(); links[next].focus({preventScroll:true}); }
});
links.forEach(function(link){
  link.addEventListener('click', function(){
    links.forEach(function(o){ o.classList.remove('mn4-mega-columns-current'); o.removeAttribute('aria-current'); });
    link.classList.add('mn4-mega-columns-current');
    link.setAttribute('aria-current', 'page');
    setOpen(false);
    tab.focus({preventScroll:true});
  });
});
root.addEventListener('focusout', function(){
  setTimeout(function(){ if (open && !root.contains(document.activeElement)) setOpen(false); }, 0);
});

