js:
var pin = root.querySelector('.mn4-rail-expand-pin');
var marker = root.querySelector('.mn4-rail-expand-marker');
var items = Array.prototype.slice.call(root.querySelectorAll('.mn4-rail-expand-item'));
function place(el){
  marker.style.setProperty('--mn4-re-y', el.offsetTop + 'px');
  marker.style.height = el.offsetHeight + 'px';
}
function activate(el){
  items.forEach(function(o){ o.classList.remove('mn4-rail-expand-active'); o.removeAttribute('aria-current'); });
  el.classList.add('mn4-rail-expand-active');
  el.setAttribute('aria-current', 'page');
  place(el);
}
items.forEach(function(el, i){
  el.addEventListener('click', function(){ activate(el); });
  el.addEventListener('keydown', function(e){
    var n = -1;
    if (e.key === 'ArrowDown') n = (i + 1) % items.length;
    else if (e.key === 'ArrowUp') n = (i - 1 + items.length) % items.length;
    else if (e.key === 'Home') n = 0;
    else if (e.key === 'End') n = items.length - 1;
    if (n > -1) { e.preventDefault(); items[n].focus({preventScroll:true}); }
  });
});
pin.addEventListener('click', function(){
  var next = root.getAttribute('data-pinned') !== 'true';
  root.setAttribute('data-pinned', next ? 'true' : 'false');
  pin.setAttribute('aria-pressed', next ? 'true' : 'false');
});
place(root.querySelector('.mn4-rail-expand-item.mn4-rail-expand-active') || items[0]);
if (window.requestAnimationFrame) requestAnimationFrame(function(){ place(root.querySelector('.mn4-rail-expand-item.mn4-rail-expand-active') || items[0]); });

