var track = root.querySelector('.mn4-crumb-collapse-track');
var more = root.querySelector('.mn4-crumb-collapse-more');
var dots = root.querySelector('.mn4-crumb-collapse-dots');
var pop = root.querySelector('.mn4-crumb-collapse-pop');
var range = root.querySelector('.mn4-crumb-collapse-range');
var crumbs = Array.prototype.slice.call(root.querySelectorAll('.mn4-crumb-collapse-crumb'));
var widths = [];
var moreWidth = 0;
var lastHidden = -1;
function closePop(){ root.setAttribute('data-pop', 'false'); dots.setAttribute('aria-expanded', 'false'); }
function measure(){
  crumbs.forEach(function(li, i){ widths[i] = li.getBoundingClientRect().width; });
  moreWidth = more.getBoundingClientRect().width;
}
function fit(){
  var avail = track.clientWidth - 16;
  var total = 0;
  for (var i = 0; i < widths.length; i++) total += widths[i];
  var hidden = 0;
  var hideable = crumbs.length - 2;
  while (total + (hidden ? moreWidth : 0) > avail && hidden < hideable) {
    total -= widths[1 + hidden];
    hidden++;
  }
  if (hidden === lastHidden) return;
  lastHidden = hidden;
  crumbs.forEach(function(li, idx){ li.classList.toggle('mn4-crumb-collapse-hidden', idx >= 1 && idx <= hidden); });
  more.classList.toggle('mn4-crumb-collapse-hidden', hidden === 0);
  dots.setAttribute('aria-label', 'Show ' + hidden + ' hidden level' + (hidden === 1 ? '' : 's'));
  if (hidden === 0) closePop();
  pop.innerHTML = '';
  for (var k = 1; k <= hidden; k++) {
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'mn4-crumb-collapse-popitem';
    b.setAttribute('role', 'menuitem');
    b.textContent = crumbs[k].textContent.trim();
    pop.appendChild(b);
  }
}
measure();
more.classList.add('mn4-crumb-collapse-hidden');
fit();
dots.addEventListener('click', function(){
  var next = root.getAttribute('data-pop') !== 'true';
  root.setAttribute('data-pop', next ? 'true' : 'false');
  dots.setAttribute('aria-expanded', next ? 'true' : 'false');
  if (next) { var first = pop.querySelector('.mn4-crumb-collapse-popitem'); if (first) first.focus({preventScroll:true}); }
});
pop.addEventListener('click', function(e){
  if (e.target && e.target.classList.contains('mn4-crumb-collapse-popitem')) { closePop(); dots.focus({preventScroll:true}); }
});
pop.addEventListener('keydown', function(e){
  var list = Array.prototype.slice.call(pop.children);
  var i = list.indexOf(document.activeElement);
  if (e.key === 'ArrowDown') { e.preventDefault(); list[(i + 1) % list.length].focus({preventScroll:true}); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); list[(i - 1 + list.length) % list.length].focus({preventScroll:true}); }
});
root.addEventListener('keydown', function(e){
  if (e.key === 'Escape' && root.getAttribute('data-pop') === 'true') { e.stopPropagation(); closePop(); dots.focus({preventScroll:true}); }
});
range.addEventListener('input', function(){ root.style.setProperty('--mn4-cc-w', range.value + 'px'); });
if (window.ResizeObserver) { new ResizeObserver(function(){ fit(); }).observe(track); }
root.addEventListener('focusout', function(){
  setTimeout(function(){ if (root.getAttribute('data-pop') === 'true' && !root.contains(document.activeElement)) closePop(); }, 0);
});

