js:
var trigger = root.querySelector('.mn4-kebab-pop-trigger');
var items = Array.prototype.slice.call(root.querySelectorAll('.mn4-kebab-pop-item'));
var check = root.querySelector('.mn4-kebab-pop-check');
var danger = root.querySelector('.mn4-kebab-pop-danger');
var dangerTxt = root.querySelector('.mn4-kebab-pop-txt');
var undo = root.querySelector('.mn4-kebab-pop-undo');
var confirmTimer = null;
var open = false;
function resetConfirm(){
  if (confirmTimer) { clearTimeout(confirmTimer); confirmTimer = null; }
  danger.setAttribute('data-confirm', 'false');
  dangerTxt.textContent = 'Delete draft';
}
function setOpen(v){
  open = v;
  root.setAttribute('data-open', v ? 'true' : 'false');
  trigger.setAttribute('aria-expanded', v ? 'true' : 'false');
  if (!v) resetConfirm();
  else items[0].focus({preventScroll:true});
}
trigger.addEventListener('click', function(){
  if (open) { setOpen(false); trigger.focus({preventScroll:true}); } else { setOpen(true); }
});
trigger.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown') { e.preventDefault(); setOpen(true); }
});
root.addEventListener('keydown', function(e){
  if (e.key === 'Escape' && open) { e.stopPropagation(); setOpen(false); trigger.focus({preventScroll:true}); return; }
  if (!open) return;
  var i = items.indexOf(document.activeElement);
  if (e.key === 'ArrowDown') { e.preventDefault(); items[(i + 1) % items.length].focus({preventScroll:true}); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); items[(i - 1 + items.length) % items.length].focus({preventScroll:true}); }
  else if (e.key === 'Tab') { setOpen(false); }
});
items.forEach(function(item){
  item.addEventListener('click', function(){
    if (item === check) {
      var on = check.getAttribute('aria-checked') === 'true';
      check.setAttribute('aria-checked', on ? 'false' : 'true');
      return;
    }
    if (item === danger) {
      if (danger.getAttribute('data-confirm') !== 'true') {
        danger.setAttribute('data-confirm', 'true');
        dangerTxt.textContent = 'Tap again to confirm';
        confirmTimer = setTimeout(resetConfirm, 2600);
        return;
      }
      setOpen(false);
      root.setAttribute('data-deleted', 'true');
      setTimeout(function(){ undo.focus({preventScroll:true}); }, 120);
      return;
    }
    setOpen(false);
    trigger.focus({preventScroll:true});
  });
  if (item !== danger) item.addEventListener('focus', resetConfirm);
});
undo.addEventListener('click', function(){
  root.setAttribute('data-deleted', 'false');
  trigger.focus({preventScroll:true});
});
root.addEventListener('focusout', function(){
  setTimeout(function(){ if (open && !root.contains(document.activeElement)) setOpen(false); }, 0);
});

