var rows = Array.prototype.slice.call(root.querySelectorAll('.mn4-tree-nested-row'));
function groupOf(row){ var li = row.parentElement; return li ? li.querySelector('.mn4-tree-nested-group') : null; }
function isBranch(row){ return row.classList.contains('mn4-tree-nested-branch'); }
function shown(row){
  var el = row.parentElement;
  while (el && el !== root) {
    if (el.classList.contains('mn4-tree-nested-group') && !el.classList.contains('mn4-tree-nested-open')) return false;
    el = el.parentElement;
  }
  return true;
}
function visibleRows(){ return rows.filter(shown); }
function focusRow(row){
  if (!row) return;
  rows.forEach(function(r){ r.setAttribute('tabindex', '-1'); });
  row.setAttribute('tabindex', '0');
  row.focus({preventScroll:true});
}
function toggle(row, force){
  var g = groupOf(row);
  if (!g) return false;
  var next = typeof force === 'boolean' ? force : !g.classList.contains('mn4-tree-nested-open');
  g.classList.toggle('mn4-tree-nested-open', next);
  row.setAttribute('aria-expanded', next ? 'true' : 'false');
  return true;
}
function select(row){
  rows.forEach(function(r){ r.classList.remove('mn4-tree-nested-active'); r.removeAttribute('aria-selected'); });
  row.classList.add('mn4-tree-nested-active');
  row.setAttribute('aria-selected', 'true');
}
rows.forEach(function(row){
  row.addEventListener('click', function(){
    focusRow(row);
    if (isBranch(row)) toggle(row);
    else select(row);
  });
  row.addEventListener('keydown', function(e){
    var list = visibleRows();
    var i = list.indexOf(row);
    if (e.key === 'ArrowDown') { e.preventDefault(); focusRow(list[Math.min(list.length - 1, i + 1)]); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); focusRow(list[Math.max(0, i - 1)]); }
    else if (e.key === 'ArrowRight') {
      e.preventDefault();
      if (isBranch(row) && row.getAttribute('aria-expanded') === 'false') toggle(row, true);
      else focusRow(visibleRows()[i + 1]);
    }
    else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      if (isBranch(row) && row.getAttribute('aria-expanded') === 'true') { toggle(row, false); return; }
      var parentGroup = row.parentElement ? row.parentElement.parentElement : null;
      if (parentGroup && parentGroup.classList.contains('mn4-tree-nested-group')) {
        var parentRow = parentGroup.parentElement.querySelector('.mn4-tree-nested-row');
        focusRow(parentRow);
      }
    }
    else if (e.key === 'Home') { e.preventDefault(); focusRow(list[0]); }
    else if (e.key === 'End') { e.preventDefault(); focusRow(list[list.length - 1]); }
    else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (isBranch(row)) toggle(row); else select(row);
    }
  });
});
